<template>
  <div v-loading="loading" class="dynamic-form-shell">
    <el-form :model="formData" label-width="120px" ref="formRef" label-position="top" :validate-on-rule-change="false" class="dynamic-form">
      <div v-for="field in appFields" :key="field.id">
        <el-form-item :label="field.field_label" :required="field.required">
          <!-- 根据字段类型渲染不同控件 -->
          <el-input v-if="field.field_type === 'text'" v-model="formData[field.field_name]" :placeholder="field.placeholder" />
          <el-input v-if="field.field_type === 'user_name'" v-model="formData[field.field_name]" disabled />
          <el-input v-if="field.field_type === 'textarea'" type="textarea" v-model="formData[field.field_name]" :placeholder="field.placeholder" />
          <el-input-number v-if="field.field_type === 'number'" v-model="formData[field.field_name]" style="width: 100%" />
          <el-date-picker v-if="field.field_type === 'date'" v-model="formData[field.field_name]" type="date" style="width: 100%" value-format="YYYY-MM-DD" :teleported="false" />
          <el-select v-if="field.field_type === 'select'" v-model="formData[field.field_name]" style="width: 100%" :teleported="false">
            <el-option v-for="opt in (fieldOptions[field.id] || field.options || [])" :key="opt.value" :label="opt.label" :value="opt.value" />
          </el-select>
          <el-select v-if="field.field_type === 'approver_teacher'" v-model="formData[field.field_name]" placeholder="选择审批老师" style="width: 100%" :teleported="false">
            <el-option
              v-for="user in teachers"
              :key="user.id"
              :label="`${user.name} (${user.role || '未知'})`"
              :value="user.id"
            />
          </el-select>
          <el-select v-if="field.field_type === 'equipment_select'" v-model="formData[field.field_name]" placeholder="请选择可用设备" style="width: 100%" filterable :teleported="false">
            <el-option 
              v-for="eq in equipments" 
              :key="eq.id" 
              :label="`${eq.name} (${eq.model}) @${eq.location || '未知位置'} | 在库: ${eq.available_quantity ?? 0}`" 
              :value="eq.id" 
              :disabled="eq.available_quantity <= 0"
            />
          </el-select>
          <el-upload
            v-if="field.field_type === 'file'"
            :auto-upload="false"
            :limit="1"
            accept="image/*"
            :on-change="(file) => handleImageChange(file, field.field_name)"
          >
            <el-button type="primary" plain>选择图片</el-button>
          </el-upload>
          <el-image
            v-if="field.field_type === 'file' && formData[field.field_name]"
            :src="formData[field.field_name]"
            fit="contain"
            style="width: 120px; height: 120px; margin-top: 8px"
            :preview-src-list="[formData[field.field_name]]"
          />
        </el-form-item>
      </div>
    </el-form>

    <!-- 流程预览 -->
    <div v-if="flowNodes && flowNodes.length" class="flow-preview mt-6">
      <div class="preview-title mb-4">
        <el-icon class="mr-1"><Notification /></el-icon>
        <span>审批流程预览</span>
      </div>
      <div class="flow-steps-wrap">
        <el-steps :active="1" finish-status="success" align-center>
          <el-step 
            v-for="node in flowNodes" 
            :key="node.node_id" 
            :title="node.name"
            :description="getNodeDescription(node)"
          />
        </el-steps>
      </div>
    </div>

    <div class="form-footer mt-6 text-right">
      <el-button class="footer-btn" @click="$emit('cancel')">取消</el-button>
      <el-button class="footer-btn primary-btn" type="primary" @click="submitForm" :loading="submitting">提交申请</el-button>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, reactive, watch, computed } from 'vue'
import { ElMessage } from 'element-plus'
import { Notification } from '@element-plus/icons-vue'
import api from '@/api'

const props = defineProps({
  appCode: {
    type: String,
    required: true
  },
  initialData: {
    type: Object,
    default: () => ({})
  }
})

const emit = defineEmits(['success', 'cancel'])

const loading = ref(false)
const submitting = ref(false)
const appData = ref(null)
const appFields = ref([])
const teachers = ref([])
const equipments = ref([])
const flowNodes = ref([])
const formData = reactive({})
const currentUser = ref(JSON.parse(localStorage.getItem('user') || 'null'))
const fieldOptions = ref({}) // 存储 select 字段的动态选项 {fieldId: [{value, label}]}

/** 采购「紧急程度」等：库表 options 与 field_option 都为空时的兜底 */
const SELECT_FALLBACK_BY_FIELD_NAME = {
  urgency: [
    { value: 'normal', label: '普通' },
    { value: 'urgent', label: '紧急' },
    { value: 'critical', label: '特急' }
  ]
}

/** 把后端 options 统一成 { value, label }[]（支持 JSON 字符串、{id,name}、{key,label}） */
function normalizeSelectOptions (raw) {
  if (raw == null || raw === '') return []
  let arr = raw
  if (typeof raw === 'string') {
    try {
      arr = JSON.parse(raw)
    } catch {
      return []
    }
  }
  if (!Array.isArray(arr)) return []
  return arr
    .map((opt) => {
      if (opt == null) return null
      if (typeof opt === 'object') {
        const value = opt.value ?? opt.id ?? opt.key
        const label = opt.label ?? opt.name ?? (value != null ? String(value) : '')
        if (value == null && !label) return null
        return { value: value != null ? value : label, label: label || String(value) }
      }
      return { value: opt, label: String(opt) }
    })
    .filter(Boolean)
}

const getNodeDescription = (node) => {
  if (node.type === 'start') return '本人发起'
  if (node.type === 'end') return '完成'
  
  // 尝试匹配表单中的审批人
  const approverId = formData.approver_id
  if (approverId && (node.name.includes('审批') || node.name.includes('审核'))) {
    const teacher = teachers.value.find(t => t.id === approverId)
    return teacher ? `审批人: ${teacher.name}` : '待指定审批人'
  }
  return '系统流程'
}

const fetchTeachers = async () => {
  try {
    const res = await api.getUsers({ role: 'teacher' })
    teachers.value = res.data.results || res.data || []
  } catch (error) {
    console.error('加载老师列表失败')
  }
}

const fetchEquipments = async () => {
  try {
    const res = await api.getEquipments()
    equipments.value = res.data?.results || res.data || []
  } catch (error) {
    console.error('Fetch equipments error:', error)
  }
}

const loadFieldOptions = async (field) => {
  if (field.field_type !== 'select') return
  const staticOpts = normalizeSelectOptions(field.options)
  const fallback = SELECT_FALLBACK_BY_FIELD_NAME[field.field_name] || []
  const base = staticOpts.length > 0 ? staticOpts : fallback
  try {
    const res = await api.getLowCodeFieldOptions(field.id)
    const apiOpts = Array.isArray(res.data) ? res.data : []
    const apiNorm = apiOpts.map((o) => ({
      value: o.value,
      label: o.label != null ? o.label : String(o.value)
    })).filter((o) => o.value != null)
    // API 有数据用 API；否则保留静态/兜底，绝不能被 [] 覆盖掉
    fieldOptions.value[field.id] = apiNorm.length > 0 ? apiNorm : base
  } catch (error) {
    console.error('Load field options failed for field', field.id, error)
    fieldOptions.value[field.id] = base.length > 0 ? base : fallback
  }
}

const fetchAppData = async () => {
  if (!props.appCode) return
  loading.value = true
  try {
    const res = await api.getLowCodeAppDetail(props.appCode)
    if (res.data && res.data.length > 0) {
      appData.value = res.data[0]
      if (appData.value.forms && appData.value.forms.length > 0) {
        // 多张表单时不要用 forms[0]：取「字段最多」的一张，避免旧空壳表单排在前面导致缺「紧急程度」等字段
        let bestForm = appData.value.forms[0]
        for (const fm of appData.value.forms) {
          const n = fm.fields?.length || 0
          if (n > (bestForm.fields?.length || 0)) bestForm = fm
        }
        appFields.value = [...(bestForm.fields || [])].sort((a, b) => a.sort_order - b.sort_order)
        // 自动填充默认值逻辑 + 为 select 字段加载动态选项
        for (const f of appFields.value) {
          // 修正：initialData 可能是响应式的，需处理 null/undefined 兜底
          let val = (props.initialData && props.initialData[f.field_name]) ?? f.default_value ?? ''

          if (f.field_type === 'user_name' && !val) {
            val = currentUser.value?.name
          }

          formData[f.field_name] = val

          if (f.field_type === 'select') {
            await loadFieldOptions(f)
          }
        }
      }
      // 获取流程配置
      if (appData.value.flows && appData.value.flows.length > 0) {
        // 简单按 node_id 排序展示流程
        flowNodes.value = [...appData.value.flows[0].nodes].sort((a, b) => a.node_id - b.node_id)
      }
    }
  } catch (error) {
    console.error('Fetch app data error:', error)
    ElMessage.error('加载应用配置失败')
  } finally {
    loading.value = false
  }
}

const submitForm = async () => {
  for (const f of appFields.value) {
    if (!f.required) continue
    const v = formData[f.field_name]
    if (v === null || v === undefined || String(v).trim() === '') {
      return ElMessage.warning(`请填写：${f.field_label}`)
    }
    if (f.field_type === 'number' && (v === '' || Number(v) === 0)) {
      const label = f.field_label || ''
      if (label.includes('人数') || label.includes('天数') || label.includes('数量')) {
        return ElMessage.warning(`请填写有效的：${f.field_label}`)
      }
    }
  }
  console.log('[DynamicForm] Submitting formData:', JSON.stringify(formData))
  submitting.value = true
  try {
    const payload = {
      app_code: props.appCode,
      form_data: { ...formData },
      user_id: currentUser.value?.id
    }
    console.log('[DynamicForm] Payload to backend:', JSON.stringify(payload))
    await api.createLowCodeInstance(payload)
    ElMessage.success('提交成功')
    emit('success')
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '提交失败'))
  } finally {
    submitting.value = false
  }
}

const handleImageChange = (uploadFile, fieldName) => {
  const raw = uploadFile?.raw
  if (!raw) return
  const reader = new FileReader()
  reader.onload = () => {
    formData[fieldName] = reader.result
  }
  reader.readAsDataURL(raw)
}

watch(() => props.appCode, () => {
  fetchAppData()
}, { immediate: true })

onMounted(() => {
  fetchTeachers()
  fetchEquipments()
})
</script>

